package com.almaraama.shared.id;

import java.util.Objects;
import java.util.UUID;

/** Public identifier of a person (identity module), referenced by every module (CF-2, CF-10). */
public record PersonId(UUID value) {

    public PersonId {
        Objects.requireNonNull(value, "value");
    }

    /** A new UUID v7 identifier, generated by the application (CF-10). */
    public static PersonId newId() {
        return new PersonId(UuidV7.next());
    }

    /** Reads an identifier from its text form, for example the subject of an access token. */
    public static PersonId of(String value) {
        return new PersonId(UUID.fromString(value));
    }

    /** The UUID in its canonical text form. */
    @Override
    public String toString() {
        return value.toString();
    }
}
